-- a tabela tem 1000 pedidos, 200 com status NULL
SELECT count(*) FROM pedido WHERE status <> 'cancelado';
-- 750, não 950: as 200 linhas com NULL sumiram

-- as três formas de incluir o desconhecido de volta
SELECT count(*) FROM pedido WHERE status <> 'cancelado' OR status IS NULL;
SELECT count(*) FROM pedido WHERE status IS DISTINCT FROM 'cancelado';
SELECT count(*) FROM pedido WHERE coalesce(status, '') <> 'cancelado';

